import { GAStringWrapper} from './GAStringWrapper';
import { GANumberWrapper} from './GANumberWrapper';
import { GASystem} from './GASystem/GASystem';

export * from './GAStringWrapper';
export const initTesting = (txt: string) => {
    return new GAStringWrapper(txt);
};
export * from './GANumberWrapper';
export const initTestingNum = (txt: number = 4) => {
    return new GANumberWrapper(txt);
};
export * from './GASystem/GASystem';
export const initTestingNetwork = (txt: number = 4) => {
    return GASystem.Init();
};